<template><section class="container-main section-padding"><form class="pc-card mx-auto max-w-2xl space-y-4" @submit.prevent="save"><p class="pc-kicker">Supplier onboarding</p><h1 class="text-3xl font-bold text-white">Complete your supplier profile</h1><input v-model="form.company_name" class="input-field" required placeholder="Legal company name"/><input v-model="form.company_country" class="input-field" required placeholder="Country"/><input v-model="form.company_city" class="input-field" placeholder="City"/><input v-model="form.company_website" class="input-field" placeholder="Website"/><textarea v-model="form.company_description" class="input-field" placeholder="Products, services, certifications and delivery coverage"/><p v-if="error" class="text-red-300">{{ error }}</p><button class="btn-primary w-full">Finish onboarding</button></form></section></template>
<script setup lang="ts">definePageMeta({layout:'procurement',middleware:['auth']});const api=useCommerce();const error=ref('');const form=reactive({company_name:'',company_country:'',company_city:'',company_website:'',company_description:''});async function save(){try{await api.updateSupplierAccount(form);await navigateTo('/supplier/dashboard')}catch(e:any){error.value=e?.data?.detail||e?.message}}onMounted(async()=>{try{const x=await api.getSupplierAccount();Object.assign(form,{company_name:x.company?.name||'',company_country:x.company?.country||'',company_city:x.company?.city||'',company_website:x.company?.website||'',company_description:x.company?.description||''})}catch(e:any){error.value=e?.data?.detail||e?.message}})</script>
